    [264908] = { enName = "Ancient Heirloom", enDescription = "Deep dents and scratches mar the dull surface of the intricate Kaldorei patterns. Faded but legible script on the inside of the band reads 'With love always, KG'.", description = "Profondi ammaccature e graffi rovinano la superficie opaca degli intricati motivi Kaldorei. Una scritta sbiadita ma leggibile all'interno della fascia recita «Con amore, per sempre, KG»." },
    [265105] = { enName = "Lady's Tear Moss", enDescription = "This cool and stringy moss feels slightly damp and seems to stick to your fingers.", description = "Questo muschio fresco e filamentoso è leggermente umido e sembra attaccarsi alle dita." },
    [265140] = { enName = "Pristine Shriekling Feather", enDescription = "These feathers are soft and just slightly oily. Perfect for insulation against the cool, damp climates of Shadowgale Forest.", description = "Queste piume sono morbide e appena oleose. Perfette per isolarsi dal clima fresco e umido della Shadowgale Forest." },
    [265141] = { enName = "Bloody Heirloom", enDescription = "Drenched in the blood of those who were once were promised a brighter future.", description = "Inzuppato nel sangue di coloro a cui era stata promessa una volta una prospettiva più luminosa." },
    [265475] = { enName = "Commander Haalien's Severed Head", enDescription = "At least now his traitorous tongue is silenced.", description = "Almeno ora la sua lingua traditrice è messa a tacere." },
    [265476] = { enName = "Ripped Missive", enDescription = "This crumpled missive is written in elegant handwriting.", description = "Questo messaggio spiegazzato è scritto con una grafia elegante." },
    [265782] = { enName = "Mysterious Orders", enDescription = "This missive contains orders from someone located in Valanaar. From the elegant script it seems like a person of status.", description = "Questo messaggio contiene ordini di qualcuno che si trova a Valanaar. Dalla grafia elegante, sembra provenire da una persona di alto rango." },
    [266252] = { enName = "Damaged Locket", enDescription = "The locket is sealed shut by a broken clasp.", description = "Il medaglione è chiuso da un fermaglio rotto." },
    [266433] = { enName = "Abandoned Belongings", enDescription = "Crates and baskets with half-packed belongings falling out of them. Whoever gathered this left in a hurry.", description = "Casse e ceste da cui fuoriescono oggetti personali impacchettati a metà. Chiunque li abbia raccolti è partito in fretta." },
    [267001] = { enName = "Ketharas' Empty Vial", enDescription = "A simple vial made of fused glass, for collecting pure water.", description = "Una semplice fiala di vetro fuso, per raccogliere acqua pura." },
    [267178] = { enName = "Wheeler's Steed Feed", enDescription = "Straight to the horse's mouth!", description = "Direttamente dalla bocca del cavallo!" },
    [267244] = { enName = "Care Package", enDescription = "To: Freddie, From: Eleanor", description = "A: Freddie, Da: Eleanor" },
    [267341] = { enName = "Sweetpaw Jam", enDescription = "Never get between a furbolg and their favorite tasty treat.", description = "Non metterti mai tra un furbolg e la sua leccornia preferita." },
    [268298] = { enName = "Concoction of Cleansing", enDescription = "This concoction purges fel corruption from afflicted animals.", description = "Questa miscela purga la corruzione vil dagli animali afflitti." },
    [268336] = { enName = "Improved Concoction of Cleansing", enDescription = "This upgraded concoction purges fel corruption from afflicted animals.", description = "Questa miscela potenziata purga la corruzione vil dagli animali afflitti." },
    [268423] = { enName = "Whisker of Shalla'kal", enDescription = "Surprisingly long.", description = "Sorprendentemente lungo." },
    [268647] = { enName = "Big Ball o' Bait", enDescription = "A knotted mess of various entrails.", description = "Un groviglio annodato di varie interiora." },
    [268664] = { enName = "Rotflesh Mushroom", enDescription = "Smells like death. Tastes like it too.", description = "Sa di morte. E anche il sapore è quello." },
    [268677] = { enName = "Barkskin Purification Tonic", enDescription = "The leather smells of rainfall and beeswax.", description = "La pelle odora di pioggia e cera d'api." },
    [268813] = { enName = "Fel Ash Sample", enDescription = "The acrid smell of brimestone wafts off the pile, causing a burning sensation in the nose and throat if accidently inhaled. It is warm to the touch and glows softly with latent Fel energy.", description = "Dal mucchio esala un odore acre di brimestone, che provoca una sensazione di bruciore al naso e alla gola se inalato accidentalmente. È caldo al tatto e brilla debolmente di energia Vil latente." },
    [268814] = { enName = "Sludgy Bits", enDescription = "Pieces of something that didn't quite liquify...", description = "Frammenti di qualcosa che non si è del tutto liquefatto..." },
    [268815] = { enName = "Bone Fragments", enDescription = "To small to identify, yet sharp enough to leave a nasty cut.", description = "Troppo piccolo per essere identificato, ma abbastanza affilato da lasciare un brutto taglio." },
    [268967] = { enName = "Token of the Wild King", enDescription = "This crude necklace bears a passing resemblance to a... bear? Stag? Eagle? Steaglebear?", description = "Questa rozza collana somiglia vagamente a un... orso? Cervo? Aquila? Steaglebear?" },
    [268990] = { enName = "Pristine Fel-Slime Crystal", enDescription = "This flawless crystal hums softly in your hands and emits a faint light. An ashen hue seems to cover its dull surface and fel ash veins create an intricate pattern within.", description = "Questo cristallo perfetto vibra dolcemente tra le mani ed emana una luce fioca. Una tonalità cinerea sembra ricoprire la sua superficie opaca e vene di cenere vil creano al suo interno un intricato motivo." },
    [268998] = { enName = "Omnuron's Spear", enDescription = "This spear is decorated with trinkets of the air and hums slightly with the power of the sky.", description = "Questa lancia è decorata con ninnoli dell'aria e vibra leggermente per il potere del cielo." },
    [269008] = { enName = "Corrupted Grovewalker Sap", enDescription = "Thick and almost gellationous in consistancy, this sap seems to be as acrid as it is thick.", description = "Densa e quasi gelatinosa per consistenza, questa linfa sembra essere tanto acre quanto densa." },
    [269011] = { enName = "Ash-tainted Sap", enDescription = "The sap leaves a painful burn with any skin it comes in contact with.", description = "La linfa lascia una dolorosa bruciatura sulla pelle con cui entra in contatto." },
    [269013] = { enName = "Altered Concoction of Cleansing", enDescription = "This concoction alters the corruption in animals afflicted by fel energies.", description = "Questa mistura altera la corruzione negli animali afflitti dalle energie vil." },
    [269233] = { enName = "Ashen Infused Crystal", enDescription = "As you hold this crystal, it almost feels as if somthing is writhing within it.", description = "Mentre tieni questo cristallo, sembra quasi che qualcosa si contorca al suo interno." },
    [269247] = { enName = "Inert Phylactery", enDescription = "The soul of the lich no longer stirs within.", description = "L'anima del lich non si agita più al suo interno." },
    [269326] = { enName = "NOT USED", enDescription = "NOT USED", description = "NON USATO" },
    [269327] = { enName = "Edge of Oblivion", enDescription = "Umbrinoth", description = "Umbrinoth" },
    [269757] = { enName = "Battered Zeppelin Parcel", enDescription = "Fragile.", description = "Fragile." },
    [269758] = { enName = "Quest Reward Placeholder", enDescription = "Some day I'll be a real item...", description = "Un giorno sarò un vero oggetto..." },
    [269759] = { enName = "Quest Reward Placeholder", enDescription = "Some day I'll be a real item...", description = "Un giorno sarò un vero oggetto..." },
    [269774] = { enName = "Unusual Ooze Vial", enDescription = "A highly viscous and slightly luminous green ooze clings to the glass.", description = "Una sostanza melmosa verde, molto viscosa e leggermente luminosa, aderisce al vetro." },
    [269777] = { enName = "Quicklatch Sparker", enDescription = "A small contraption to quickly conjure sparks and a flame with the flick of a finger.", description = "Un piccolo congegno per evocare rapidamente scintille e una fiamma con uno schiocco di dita." },
    [269810] = { enName = "Scrapper's Salvage", enDescription = "Pick your part!", description = "Scegli il tuo pezzo!" },
    [269901] = { enName = "Schematic: Centaur Banner Deployment Device", enDescription = "Teaches you how to craft Centaur Banner Deployment Device.", description = "Insegna a creare il Dispositivo di Dispiegamento dello Stendardo dei Centauri." },
    [269903] = { enName = "Schematic: Hoof-Shaped Foot Pedal", enDescription = "Teaches you how to craft Hoof-Shaped Foot Pedal.", description = "Insegna a creare il Pedale a Forma di Zoccolo." },
    [270151] = { enName = "Benedict's Orders", enDescription = "Orders from Lieutenant Benedict from Tiragarde Keep.", description = "Ordini del tenente Benedict da Roccaforte di Tiragarde." },
    [270298] = { enName = "Unholy Icon", enDescription = "Power begets power. This is but a taste of what awaits you...", description = "Il potere genera potere. Questo è solo un assaggio di ciò che ti attende..." },
    [270308] = { enName = "The First Tablet of I'lalai", enDescription = "A Fate in Blood", description = "Un destino nel sangue" },
    [270309] = { enName = "The Second Tablet of I'lalai", enDescription = "The First Tidebearer", description = "Il Primo Portatore di Maree" },
    [270310] = { enName = "The Third Tablet of I'lalai", enDescription = "The Cracked and Cursed", description = "I Frantumati e i Maledetti" },
    [270311] = { enName = "The Fourth Tablet of I'lalai", enDescription = "Loa of the Lost", description = "Loa dei Perduti" },
    [270312] = { enName = "Translated Tale of I'lalai", enDescription = "A compiled list of the translated workings from the tablets in the lost troll city of I'lalai the Drowned City.", description = "Un elenco compilato delle opere tradotte dalle tavolette della perduta città dei troll di I'lalai, la Città Sommersa." },
    [270313] = { enName = "Tale of I'lalai in Zandali", enDescription = "A compiled list of the workings from the tablets in the lost troll city of I'lalai the Drowned City, transcribed in modern Zandali by Kin'weelay.", description = "Un elenco compilato delle opere dalle tavolette della perduta città dei troll di I'lalai, la Città Sommersa, trascritte nello zandali moderno da Kin'weelay." },
    [270332] = { enName = "Fredd's Head", enDescription = "Surprisingly fresh.", description = "Sorprendentemente fresco." },
    [270333] = { enName = "Voodoo-Infused Artifact", enDescription = "These artifacts hum with latent energies and seem to pull at the various conflicting magics within the Drowned City.", description = "Questi artefatti vibrano di energie latenti e sembrano attirare le varie magie contrastanti all'interno della Città Sommersa." },
    [270436] = { enName = "Rudolph Gelhardt's Head", enDescription = "A token of loyalty from the paladins of Bandarion Keep. -Danitha Morr", description = "Un pegno di lealtà dai paladini della Rocca di Bandarion. -Danitha Morr" },
    [270887] = { enName = "Advertising License Application", enDescription = "Contains information and instructions as to how to acquire your very own Orcish Tradeskill Sign toy.", description = "Contiene informazioni e istruzioni su come ottenere il tuo personale giocattolo Insegna delle professioni orchesca." },
    [270888] = { enName = "Advertising License Application", enDescription = "Contains information and instructions as to how to acquire your very own Dwarven Tradeskill Sign toy.", description = "Contiene informazioni e istruzioni su come ottenere il tuo personale giocattolo Insegna delle professioni nanica." },
    [270901] = { enName = "Reed-woven Heart", enDescription = "Braided grass in the shape of a heart.", description = "Erba intrecciata a forma di cuore." },
    [271647] = { enName = "Once Used Shoe", enDescription = "Peering inside may lead to unpleasant discoveries.", description = "Guardare al suo interno può portare a scoperte spiacevoli." },
    [271648] = { enName = "Ogre Tooth Cleaner", enDescription = "Like new.", description = "Come nuovo." },
    [271654] = { enName = "Expired Poison", enDescription = "Does that make it twice as poisonous, or half?", description = "Questo lo rende due volte più velenoso o la metà?" },
    [271721] = { enName = "Krol'dok Ogre Key", enDescription = "It get job done.", description = "Fa il lavoro." },
    [271745] = { enName = "Bloody Map", enDescription = "A map with Dwarvish scrawl and an emphasized X.", description = "Una mappa con scarabocchi in nanico e una X messa in risalto." },
    [271770] = { enName = "Explorers' League Cartographer's Kit", enDescription = "A standard issue kit with all the tools necessary for exploring and categorizing newly explored areas.", description = "Un kit standard con tutti gli strumenti necessari per esplorare e catalogare aree appena esplorate." },
    [271771] = { enName = "Drained Crystal Fragment", enDescription = "A gem that is cool to the touch and hums gently. Strangely no light seems to filter through it.", description = "Una gemma fredda al tatto che emette un lieve ronzio. Stranamente, la luce non sembra attraversarla." },
    [271870] = { enName = "Lump of Coal", enDescription = "A useless lump of coal.", description = "Un inutile pezzo di carbone." },
    [271880] = { enName = "Activated Brimstone Carving", enDescription = "A menacing glow emanates from the strange carving.", description = "Un bagliore minaccioso emana dallo strano intaglio." },
    [271894] = { enName = "Fiery Crystal", enDescription = "A gem that is hot to the touch and hums gently. It seems to emit a small amount of light, almost like the flickering of fire.", description = "Una gemma calda al tatto che emette un lieve ronzio. Sembra emanare una piccola quantità di luce, quasi come il tremolio di una fiamma." },
    [271898] = { enName = "Charged Crystal", enDescription = "A gem that hums gently and seems to emit a static charge. On it's own it emits a tiny amount of light and small flashes can be seen right under the surface, as if a tiny storm was trapped within.", description = "Una gemma che emette un lieve ronzio e sembra sprigionare una carica statica. Da sola emana una minuscola quantità di luce, e piccoli lampi sono visibili appena sotto la superficie, come se una minuscola tempesta fosse intrappolata al suo interno." },
    [271902] = { enName = "Noxious Crystal", enDescription = "A gem that seems to emit the slightest of fumes and hums gently. It burns slightly to hold, but when dropped on the ground, new grass sprouts around it.", description = "Una gemma che sembra emanare appena qualche esalazione e che emette un lieve ronzio. Brucia leggermente al tatto, ma, se lasciata a terra, fa spuntare nuova erba tutt'intorno." },
    [271912] = { enName = "Moist Crystal", enDescription = "A gem that seems to collect condensation on the surface making it perpetually wet and hums gently.When turned in the light, it looks as if there is water trapped within the crystal itself.", description = "Una gemma che sembra accumulare condensa sulla superficie, restando perennemente bagnata, e che emette un lieve ronzio. Quando viene esposta alla luce, sembra che ci sia dell'acqua intrappolata nel cristallo stesso." },
    [271972] = { enName = "Partially Digested Journal Page", enDescription = "This page is still soggy and stinks badly.", description = "Questa pagina è ancora fradicia e puzza terribilmente." },
    [271994] = { enName = "Undermine Satchel", enDescription = "Jingles loudly from the sound of gold and useful goods inside.", description = "Tintinna rumorosamente per via dell'oro e dei beni utili che contiene." },
    [272000] = { enName = "Golden Statue", enDescription = "Only a goblin could love this, but they'd love it A LOT.", description = "Solo un goblin potrebbe amare una cosa del genere, ma la amerebbe TANTISSIMO." },
    [272001] = { enName = "Gold Ring", enDescription = "Oooh! Sparkly.", description = "Oooh! Luccicante." },
    [272011] = { enName = "Activated Ogre Lightning Rod", enDescription = "The lightning rod is humming with nature energy despite the damage it took.", description = "La verga parafulmine emette un ronzio carico di energia della natura nonostante i danni subiti." },
    [272014] = { enName = "Silver Necklace", enDescription = "Solid dwarven craftsmanship.", description = "Solida fattura nanica." },
    [272016] = { enName = "Gold Nugget", enDescription = "Eureka!", description = "Eureka!" },
    [272017] = { enName = "Nefarion's Remit", enDescription = "A draconic language document with Nefarion's seal", description = "Un documento in lingua draconica con il sigillo di Nefarion" },
    [272018] = { enName = "Overseer's License", enDescription = "A draconic language document with General Drakkisath's seal", description = "Un documento in lingua draconica con il sigillo del Generale Drakkisath" },
    [272019] = { enName = "Bronzebeard Wedding Contract", enDescription = "A detailed contract stipulating dowry and inheritance rights for the marriage of Dagran Thaurissan and Moira Bronzebeard.", description = "Un contratto dettagliato che stabilisce dote e diritti di successione per il matrimonio tra Dagran Thaurissan e Moira Bronzebeard." },
    [272020] = { enName = "Felvine Seed", enDescription = "The seed of a fel-infused plant, glowing with demonic energies.", description = "Il seme di una pianta infusa di Vil, che brilla di energie demoniache." },
    [272021] = { enName = "Ancient Memento", enDescription = "A shattered pendant with the broken seal of Shen'dralas.", description = "Un pendente frantumato con il sigillo spezzato di Shen'dralas." },
    [272022] = { enName = "Earthstone Diamond Pinky Ring", enDescription = "An ogre's pinky ring set with a fabled Draenic earthstone diamond", description = "Un anello da mignolo da ogre incastonato con un diamante di earthstone draenico leggendario" },
    [272023] = { enName = "Headmaster's Records", enDescription = "Scholomance enrollment records during the time of the great plague", description = "I registri di iscrizione a Scholomance durante il periodo della grande piaga" },
    [272024] = { enName = "Grain Shipment Records", enDescription = "Detailed grain shipment orders written by Baron Rivendare during the great plague", description = "Ordini dettagliati per la spedizione di grano, scritti dal Barone Rivendare durante la grande piaga" },
    [272025] = { enName = "Dathrohan's Correspondance", enDescription = "Saidan Dathrohan's correspondance before and during the third war", description = "La corrispondenza di Saidan Dathrohan prima e durante la terza guerra" },
    [272026] = { enName = "Ysera's Tear", enDescription = "A crystallized tear from the great dragon Ysera.", description = "Una lacrima cristallizzata del grande drago Ysera." },
    [272027] = { enName = "Mark of Xavius", enDescription = "A mark of service to the burning legion, in the name of the satyr Xavius.", description = "Un marchio di servizio alla Legione Infuocata, in nome del satiro Xavius." },
    [272028] = { enName = "Freya's Sigil", enDescription = "A stone marked with the sigil of the titan Freya", description = "Una pietra recante il sigillo della titanide Freya" },
    [272124] = { enName = "Translated Tale of I'lalai", enDescription = "A compilation of the translated workings by Loremaster Dibbs, recounting the tale of the lost troll city, I'lalai the Drowned City.", description = "Una raccolta degli scritti tradotti del Maestro del Sapere Dibbs, che narrano la storia della città troll perduta, I'lalai la Città Sommersa." },
    [272151] = { enName = "Damaged Undermine Supply Crate", itName = "Premio di Lunacupa Superiore", enDescription = "This dented and damaged crate looks like it quite literally fell off the back of a zeppelin.", description = "Questa cassa ammaccata e danneggiata sembra essere letteralmente caduta dal retro di uno zeppelin." },
    [272313] = { enName = "Ancient Hilt", enDescription = "The hilt is unfathomably ancient, but the metal that peeks through the dust and grime still shines brightly. This weapon was clearly a masterwork before it was broken.", description = "L'elsa è incredibilmente antica, ma il metallo che affiora dalla polvere e dalla sporcizia brilla ancora intensamente. Prima di rompersi, quest'arma era chiaramente un capolavoro." },
    [272314] = { enName = "Neutralizing Concoction", enDescription = "The liquid inside the vial seems to churn violently, and sticks to the glass in a way that suggests a certain amount of elasticity.", description = "Il liquido nella fiala sembra agitarsi violentemente e aderisce al vetro in un modo che suggerisce una certa elasticità." },
    [272977] = { enName = "Spare Part", enDescription = "Unusually well-preserved, this odd piece must have been forged from an alloy resistant to corrosion.", description = "Conservato insolitamente bene, questo strano pezzo deve essere stato forgiato con una lega resistente alla corrosione." },
    [273008] = { enName = "Fel-Slime Ooze", enDescription = "This ooze wriggles in your hands, and leaves burn marks on exposed skin. It seems to have a mind of its own.", description = "Questa melma si contorce tra le tue mani e lascia ustioni sulla pelle esposta. Sembra avere una volontà propria." },
